const ALIAS_PARAMETER_PREFIX = '/paigo/attribution/alias/';
/** The tag an instance carries the code its own spend is booked to in. */
const NODE_CHARGE_CODE_TAG = 'paigoChargeCode';
/** The tag an instance names whoever it hands its spend on to in. */
const NODE_PARENT_TAG = 'paigoRollsInto';

/**
 * One pocket of a business' estate. The finance system rewrites the whole set
 * whenever a team moves, so the pools are kept together in a single document
 * rather than one object each.
 */
export class AttributionPool {
    /** The code spend sitting on this pool is booked to. */
    public chargeCode: string;
    /**
     * Whoever this pool hands its spend on to, when it does not keep it. Spend
     * that reaches a pool with a parent is carried on down the chain instead of
     * being booked here.
     * @example "unit/ember"
     */
    public rollsUpTo?: string;
}

export class AttributionPoolDocument {
    public revision: string;
    public pools: Record<string, AttributionPool>;
}

/**
 * A business unit, kept as one object each because finance edits them one at a
 * time.
 */
export class AttributionUnit {
    public unitId: string;
    /** The code spend sitting on this unit is booked to. */
    public chargeCode: string;
    /**
     * Whoever this unit hands its spend on to, when it does not keep it.
     * @example "node/445566778899/us-east-1/i-0a3f19c2d4e5b6708"
     */
    public parentRef?: string;
}

/**
 * One link of an attribution chain: the code the owner books spend to when the
 * chain stops with it, and whoever it hands the spend on to when it does not.
 */
export interface AttributionOwner {
    chargeCode?: string;
    passesTo?: string;
}

/** Credentials for reading an account of the business, by account id. */
export type AccountCredentials = (accountId: string) => any;

/**
 * The charge code a cycle of owners shares. A chain that comes back around to
 * an owner it has already passed through has no end of its own, so the code the
 * members of the cycle agree on carries the spend.
 */
const sharedChargeCode = (codes: Array<string>): string => {
    const counted = codes.reduce(
        (tally, code) => {
            if (code) {
                tally[code] = (tally[code] ?? 0) + 1;
            }
            return tally;
        },
        {} as Record<string, number>,
    );
    const shared = Object.keys(counted).sort(
        (left, right) => counted[right] - counted[left] || left.localeCompare(right),
    );
    return shared[0];
};

/**
 * The attribution material a business keeps beside its onboarding record. Pools
 * and units live in the metering bucket, aliases in parameter store and nodes
 * on the instances themselves, and any of them may pass the spend it is handed
 * on to another owner.
 */
export class AttributionDirectory {
    private readonly pools: Record<string, AttributionPool>;

    private readonly bucket: string;

    private readonly prefix: string;

    private readonly credentialsForAccount: AccountCredentials;

    /** Owners already read, so a shared link is only fetched once. */
    private readonly owners: Map<string, AttributionOwner> = new Map();

    /** References already followed all the way to the code carrying them. */
    private readonly resolved: Map<string, string> = new Map();

    private constructor(
        pools: Record<string, AttributionPool>,
        bucket: string,
        prefix: string,
        credentialsForAccount: AccountCredentials,
    ) {
        this.pools = pools;
        this.bucket = bucket;
        this.prefix = prefix;
        this.credentialsForAccount = credentialsForAccount;
    }

    static async load(
        bucket: string,
        prefix: string,
        credentialsForAccount: AccountCredentials = () => undefined,
    ): Promise<AttributionDirectory> {
        const document = await getDocument<AttributionPoolDocument>(bucket, `${prefix}pools.json`);
        return new AttributionDirectory(document?.pools ?? {}, bucket, prefix, credentialsForAccount);
    }

    /**
     * The charge code that ends up carrying a usage line, following every hand
     * off the attribution material describes. An intermediate owner never keeps
     * spend it passes on, and a chain that closes on itself is booked to the
     * code its cycle shares.
     */
    async chargeCodeFor(reference: string): Promise<string> {
        if (!reference) {
            return undefined;
        }
        if (this.resolved.has(reference)) {
            return this.resolved.get(reference);
        }

        const followed: Array<string> = [];
        const codes: Array<string> = [];
        let chargeCode: string;
        let current = reference;

        while (current) {
            const repeatedAt = followed.indexOf(current);
            if (repeatedAt >= 0) {
                chargeCode = sharedChargeCode(codes.slice(repeatedAt));
                break;
            }
            followed.push(current);
            // Each link names the next one, so they can only be read in order.
            // eslint-disable-next-line no-await-in-loop
            const owner = await this.ownerFor(current);
            if (!owner) {
                break;
            }
            codes.push(owner.chargeCode);
            if (owner.chargeCode) {
                chargeCode = owner.chargeCode;
            }
            current = owner.passesTo;
        }

        this.resolved.set(reference, chargeCode);
        return chargeCode;
    }

    /**
     * The owner a single attribution reference names, wherever that owner is
     * kept.
     */
    private async ownerFor(reference: string): Promise<AttributionOwner> {
        if (this.owners.has(reference)) {
            return this.owners.get(reference);
        }
        const owner = await AttributionDirectory.read(reference, this);
        this.owners.set(reference, owner);
        return owner;
    }

    private static async read(reference: string, directory: AttributionDirectory): Promise<AttributionOwner> {
        if (reference.startsWith(POOL_REFERENCE)) {
            const pool = directory.pools[reference.slice(POOL_REFERENCE.length)];
            return pool ? { chargeCode: pool.chargeCode, passesTo: pool.rollsUpTo } : undefined;
        }
        if (reference.startsWith(UNIT_REFERENCE)) {
            const unit = await directory.unit(reference.slice(UNIT_REFERENCE.length));
            return unit ? { chargeCode: unit.chargeCode, passesTo: unit.parentRef } : undefined;
        }
        if (reference.startsWith(ALIAS_REFERENCE)) {
            // An alias is only another name for an owner, it never keeps spend.
            const target = await getParameterValue(
                `${ALIAS_PARAMETER_PREFIX}${reference.slice(ALIAS_REFERENCE.length)}`,
            );
            return target ? { passesTo: target } : undefined;
        }
        if (reference.startsWith(NODE_REFERENCE)) {
            return directory.node(reference.slice(NODE_REFERENCE.length));
        }
        return undefined;
    }

    /** One unit of the business, or undefined when there is no such unit. */
    private async unit(name: string): Promise<AttributionUnit> {
        try {
            return await getDocument<AttributionUnit>(this.bucket, `${this.prefix}${UNIT_PREFIX}${name}.json`);
        } catch (error) {
            if (error?.name === 'NoSuchKey' || error?.name === 'NotFound' || error?.name === 'AccessDenied') {
                return undefined;
            }
            throw error;
        }
    }

    /**
     * One instance of the business, read in the account and region the
     * reference names, with the codes it carries in its tags.
     */
    private async node(target: string): Promise<AttributionOwner> {
        const [accountId, region, instanceId] = target.split('/');
        if (!accountId || !region || !instanceId) {
            return undefined;
        }
        const tags = await getInstanceTags(region, instanceId, this.credentialsForAccount(accountId));
        const chargeCode = tags[NODE_CHARGE_CODE_TAG];
        const passesTo = tags[NODE_PARENT_TAG];
        if (!chargeCode && !passesTo) {
            return undefined;
        }
        return { chargeCode, passesTo };
    }
}
"
}

