/**
 * The tags carried by one instance, keyed by tag name. An instance that is no
 * longer there, or that the credentials cannot see, comes back as no tags at
 * all so callers can carry on with the rest of their work.
 */
export const getInstanceTags = async (
    region: string,
    instanceId: string,
    creds = undefined,
): Promise<Record<string, string>> => {
    try {
        const ec2Client = new EC2Client({ region, credentials: creds });
        const response = await ec2Client.send(new DescribeInstancesCommand({ InstanceIds: [instanceId] }));
        const instance = (response?.Reservations ?? [])
            .flatMap(({ Instances }) => Instances ?? [])
            .find(({ InstanceId }) => InstanceId === instanceId);
        return (instance?.Tags ?? []).reduce(
            (tags, { Key, Value }) => {
                if (Key) {
                    tags[Key] = Value;
                }
                return tags;
            },
            {} as Record<string, string>,
        );
    } catch (error) {
        if (error?.name === 'InvalidInstanceID.NotFound') {
            return {};
        }
        console.log('Error reading instance tags', instanceId, error);
        return {};
    }
};
