/**
 * The value of a single parameter, or undefined when the parameter has never
 * been written. Callers treat a missing parameter as a missing link rather
 * than as a failure, so the absence is not raised.
 */
export const getParameterValue = async (Name: string, credentials = undefined): Promise<string> => {
    const client = new SSMClient(credentials ? { credentials } : {});
    try {
        const { Parameter } = await client.send(new GetParameterCommand({ Name }));
        return Parameter?.Value;
    } catch (error) {
        if (error?.name === 'ParameterNotFound') {
            return undefined;
        }
        throw error;
    }
};
